<template><div class="art-full-height"><ElCard class="mb-3"><ElForm inline><ElFormItem label="订单状态"><ElSelect v-model="query.status" clearable class="!w-44"><ElOption v-for="x in statuses" :key="x.value" :label="x.label" :value="x.value"/></ElSelect></ElFormItem><ElFormItem><ElButton type="primary" @click="load">查询</ElButton></ElFormItem></ElForm></ElCard><ElCard><ElTable v-loading="loading" :data="rows"><ElTableColumn prop="orderNo" label="订单号" min-width="190"/><ElTableColumn prop="productName" label="服务商品" min-width="170"/><ElTableColumn prop="skuName" label="规格" min-width="130"/><ElTableColumn prop="playerName" label="陪玩师" width="120"/><ElTableColumn label="状态" width="130"><template #default="{row}"><ElTag>{{text(row.orderStatus)}}</ElTag></template></ElTableColumn><ElTableColumn prop="customerConfirmDeadline" label="确认截止" width="180"/><ElTableColumn label="操作" width="90"><template #default="{row}"><ElButton link type="primary" @click="open(row)">查看</ElButton></template></ElTableColumn></ElTable><div class="flex justify-end mt-4"><ElPagination v-model:current-page="query.current" :total="total" @change="load" layout="total,prev,pager,next"/></div></ElCard><ElDrawer v-model="visible" title="订单与服务详情" size="680px"><template v-if="detail"><ElDescriptions :column="2" border><ElDescriptionsItem label="订单号">{{detail.orderNo}}</ElDescriptionsItem><ElDescriptionsItem label="状态">{{text(detail.orderStatus)}}</ElDescriptionsItem><ElDescriptionsItem label="陪玩师">{{detail.playerName||'待分配'}}</ElDescriptionsItem><ElDescriptionsItem label="确认截止">{{detail.customerConfirmDeadline||'-'}}</ElDescriptionsItem></ElDescriptions><template v-if="detail.fulfillment"><h4>服务完成说明</h4><p>{{detail.fulfillment.completion_note}}</p><div><ElImage v-for="url in detail.fulfillment.proofUrls" :key="url" :src="url" :preview-src-list="detail.fulfillment.proofUrls" class="proof" fit="cover"/></div></template><ElAlert v-if="detail.afterSale" class="mt-4" :title="`售后状态：${detail.afterSale.after_sale_status}`" :description="detail.afterSale.description" :closable="false"/><div v-if="detail.orderStatus==='WAIT_CUSTOMER_CONFIRM'&&!detail.afterSale" class="mt-5"><ElButton type="success" @click="confirm">确认服务完成</ElButton><ElButton type="danger" @click="afterSaleVisible=true">申请售后</ElButton></div></template></ElDrawer><ElDialog v-model="afterSaleVisible" title="申请售后" width="600px"><ElForm label-width="90px"><ElFormItem label="问题类型"><ElSelect v-model="afterForm.reasonType"><ElOption label="服务未完成" value="NOT_COMPLETED"/><ElOption label="服务质量问题" value="QUALITY"/><ElOption label="其他" value="OTHER"/></ElSelect></ElFormItem><ElFormItem label="问题说明" required><ElInput v-model="afterForm.description" type="textarea" :rows="4"/></ElFormItem><ElFormItem label="问题凭证"><LocalFileUpload v-model="afterForm.proofUrl" kind="PROOF"/></ElFormItem></ElForm><template #footer><ElButton @click="afterSaleVisible=false">取消</ElButton><ElButton type="primary" @click="saveAfterSale">提交</ElButton></template></ElDialog></div></template>
<script setup lang="ts">import LocalFileUpload from'@/components/business/local-file-upload.vue';import{fetchCustomerOrders,fetchCustomerOrder,confirmCustomerOrder,createAfterSale}from'@/api/business-manage';const loading=ref(false),rows=ref<any[]>([]),total=ref(0),visible=ref(false),afterSaleVisible=ref(false),detail=ref<any>(),query=reactive({current:1,size:20,status:''}),afterForm=reactive({reasonType:'QUALITY',description:'',proofUrl:''});const statuses=[{label:'待派单',value:'WAIT_ASSIGN'},{label:'已接单',value:'ASSIGNED'},{label:'服务中',value:'IN_SERVICE'},{label:'等待确认',value:'WAIT_CUSTOMER_CONFIRM'},{label:'售后中',value:'AFTER_SALE'},{label:'已完成',value:'COMPLETED'}];async function load(){loading.value=true;try{const d=await fetchCustomerOrders(query);rows.value=d.records;total.value=d.total}finally{loading.value=false}}async function open(r:any){detail.value=await fetchCustomerOrder(r.id);visible.value=true}async function confirm(){await ElMessageBox.confirm('确认本次服务已经完成吗？','确认完成');await confirmCustomerOrder(detail.value.id);ElMessage.success('订单已完成');visible.value=false;load()}async function saveAfterSale(){if(!afterForm.description.trim())return ElMessage.warning('请填写问题说明');await createAfterSale(detail.value.id,{reasonType:afterForm.reasonType,description:afterForm.description,proofUrls:afterForm.proofUrl?[afterForm.proofUrl]:[]});ElMessage.success('售后申请已提交');afterSaleVisible.value=false;visible.value=false;load()}const text=(s:string)=>({PENDING_PAYMENT:'待付款',WAIT_ASSIGN:'待派单',ASSIGNED:'已接单',IN_SERVICE:'服务中',PENDING_CONFIRM:'待平台审核',WAIT_CUSTOMER_CONFIRM:'等待您确认',AFTER_SALE:'售后中',COMPLETED:'已完成',CANCELLED:'已取消'}[s]||s);onMounted(load)</script><style scoped>.proof{width:120px;height:120px;margin:0 12px 12px 0;border-radius:8px}</style>
